package ai.taskforge.api; import ai.taskforge.domain.*; import ai.taskforge.repo.*; import ai.taskforge.service.CurrentUser; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController { private final TaskRepository tasks;private final CurrentUser current; public DashboardController(TaskRepository t,CurrentUser c){tasks=t;current=c;} @GetMapping("/summary") Map<String,Object> summary(){var visible=current.elevated()?tasks.findAll():tasks.findByAssigneeId(current.get().getId());var today=LocalDate.now();return Map.of("total",visible.size(),"completed",visible.stream().filter(t->t.getStatus()==TaskStatus.COMPLETED).count(),"overdue",visible.stream().filter(t->t.getDueDate()!=null&&t.getDueDate().isBefore(today)&&t.getStatus()!=TaskStatus.COMPLETED).count(),"critical",visible.stream().filter(t->t.getPriority()==Priority.CRITICAL).count(),"blocked",visible.stream().filter(t->t.getStatus()==TaskStatus.BLOCKED).count(),"dueToday",visible.stream().filter(t->today.equals(t.getDueDate())).count());} }
